186:   function driver_chargePayment(uint256 amount, uint16 feeBps) public {
187:     amount = _boundAmount(amount);
188:     if (amount == 0) return;
189:     feeBps = uint16(feeBps % 10001); // 0-10000 basis points
190: 
191:     bytes8 paymentRef = _getNextPaymentRef();
192: 
193:     // Setup: Mint tokens and approve escrow
194:     token.mint(address(this), amount);
195:     supply += amount; // Track minted tokens
196:     token.approve(address(mockEscrow), amount);
197: 
198:     try
199:       wrapper.chargePayment(
200:         ERC20CommerceEscrowWrapper.ChargeParams({
201:           paymentReference: paymentRef,
202:           payer: address(this),
203:           merchant: MERCHANT,
204:           operator: address(this),
205:           token: address(token),
206:           amount: amount,
207:           maxAmount: amount,
208:           preApprovalExpiry: block.timestamp + 1 hours,
209:           authorizationExpiry: block.timestamp + 1 hours,
210:           refundExpiry: block.timestamp + 2 hours,
211:           feeBps: feeBps,
212:           feeReceiver: FEE_RECEIVER,
213:           tokenCollector: address(0),
214:           collectorData: ''
215:         })
216:       )
217:     {
218:       // Track charge (counts as both authorize and capture)
219:       totalAuthorized += amount;
220:       totalCaptured += amount;
221:     } catch {
222:       // Expected failures
223:     }
224:   }

242:   function driver_refundPayment(uint256 paymentIndex, uint256 refundAmount) public {
243:     if (paymentRefCounter == 0) return;
244: 
245:     bytes8 paymentRef = bytes8(uint64(1 + (paymentIndex % paymentRefCounter)));
246:     refundAmount = _boundAmount(refundAmount);
247:     if (refundAmount == 0) return;
248: 
249:     // Setup: Give this contract (operator) tokens for refund and approve
250:     token.mint(address(this), refundAmount);
251:     supply += refundAmount; // Track minted tokens
252:     // Note: refund flow pulls from operator, so we need approval on wrapper
253:     token.approve(address(wrapper), refundAmount);
254: 
255:     try
256:       wrapper.refundPayment(
257:         paymentRef,
258:         refundAmount,
259:         address(0), // Use default collector
260:         ''
261:       )
262:     {
263:       totalRefunded += refundAmount;
264:     } catch {
265:       // Expected failures (e.g., not operator, insufficient refundable amount)
266:     }
267:   }

